from launch_common24 import *
j=base('launch_hormone_message_control','Hormone messages: the control room','Trace a chemical message and explain a controlled response','Describe endocrine signalling and explain why suitable internal conditions matter.',2,'Directly develops C30 through Pearson7.1,7.9 and selected7.10B concepts. Core names endocrine glands and blood transport, with pancreas/insulin as a simple example. Detailed adrenaline, thyroxine feedback and reproductive hormone mechanisms are not claimed as covered.',['Blood transports substances around the body.','Cells carry out reactions using enzymes.','External conditions can change while an organism remains alive.'],['Trace gland → blood → target organ.','Explain why a circulating hormone does not affect every cell equally.','Explain homeostasis as regulation within suitable limits rather than perfect stillness.'],[('hormone','A chemical messenger released by an endocrine gland and carried in blood.'),('endocrine gland','An organ or tissue that releases hormones into the bloodstream.'),('target cell','A cell able to respond to a particular hormone, usually because it has the appropriate receptor.'),('receptor','A molecule that recognises a signal and can trigger a response.'),('homeostasis','Regulation of internal conditions within suitable limits despite change.'),('negative feedback','A response that reduces the original departure from a regulated condition.')])
j['sources'] += [source('NIDDK: What is diabetes?','https://www.niddk.nih.gov/health-information/diabetes/overview/what-is-diabetes','Checked the pancreas–insulin example. No diagnostic threshold, medicine choice or treatment advice is taught.'),source('OpenStax Anatomy and Physiology2e: An overview of the endocrine system','https://openstax.org/books/anatomy-and-physiology-2e/pages/17-1-an-overview-of-the-endocrine-system','Checked endocrine transport and target-cell specificity; diagrams and classroom cases are original.')]
j['misconceptions']=[misconception('A hormone travels only through a private tube to one organ.','It circulates in blood; target cells respond because they can recognise the signal.','Ask why a nearby non-target cell may not respond.'),misconception('Every cell responds identically to every hormone.','Cells differ in receptors and response machinery.','Compare the two target-cell models.'),misconception('Homeostasis means a condition never changes.','Regulation limits departures; suitable ranges and dynamic adjustment matter.','Ask whether a small change automatically means control has failed.'),misconception('All homeostatic responses must use hormones.','Homeostasis can involve nervous and hormonal coordination.','Distinguish the general control idea from the endocrine example.')]
v1=visual('One message, three important locations','Endocrine transport model: an endocrine gland releases a hormone into circulating blood; the hormone reaches tissues, but only appropriate target cells respond. Arrows show information/material transport, not a private gland-to-organ duct.',[rect(45,160,265,170),text(65,185,225,120,'Endocrine gland\nReleases hormone\ninto blood',28,True,'center'),line(320,245,360,245,True),rect(375,160,250,170),text(395,200,210,90,'Bloodstream\nCarries hormone',28,True,'center'),line(635,245,675,245,True),rect(690,160,265,170),text(710,185,225,120,'Target cells\nRecognise signal\nChange activity',28,True,'center'),text(60,420,880,90,'The bloodstream distributes the signal.\nCell recognition helps determine the response.',28,align='center')])
v2=visual('A circulating hormone needs a matching response','Simplified receptor model: a purple signal is present near two cells. CellA has a matching receptor and can respond; cellB lacks that receptor. Shapes model recognition only; real receptors are molecules, not conscious locks.',[ellipse(110,165,290,220),ellipse(600,165,290,220,fill='#EEF0F3',stroke=INK),rect(245,130,40,60,fill='#FFFFFF',stroke=PURPLE),ellipse(247,104,36,36,fill=PURPLE,stroke=PURPLE),ellipse(727,104,36,36,fill=PURPLE,stroke=PURPLE),text(80,405,350,90,'CellA: matching receptor\nA response can occur',27,True,'center'),text(570,405,350,90,'CellB: no matching receptor\nNo response to this signal',26,True,'center'),text(150,235,210,75,'Specific\nresponse',29,True,'center'),text(640,235,210,75,'Same blood\nsignal present',28,True,'center')])
v3=boxes('Control reduces a departure','General negative-feedback model: a condition departs from a suitable range, the change is detected/coordinated, a response opposes the departure, and the condition moves towards the range. This is a control concept, not a claim that all responses are hormonal.', ['Condition departs\nfrom a suitable range','Change is detected\nand coordinated','Condition moves\ntowards suitable limits','Response counteracts\nthe original change'],footer='Homeostasis is active regulation, not perfect stillness.')
glands=[['Pituitary','Base of brain'],['Thyroid','Neck'],['Pancreas','Upper abdomen'],['Adrenal glands','Above the kidneys'],['Ovaries','Pelvis'],['Testes','Scrotum']]
j['slides']=[slide('Opening',2,'How does a cell receive the right message?',['A hormone can travel around the body in blood.','Why does every cell not react in the same way?'],'Invite a prediction without calling hormones thinking agents. Preview signal route, recognition and control.'),slide('Retrieval',3,'Transport and conditions',['R1. What carries many dissolved substances around the body?','R2. Why do cells need suitable conditions?','R3. Does a chemical messenger think or choose?'],'R1blood. R2cell reactions/enzymes work effectively under suitable conditions. R3no; interactions are physical/chemical. Accept plain-language mechanisms.'),slide('I do',4,'I trace the message route',['Gland releases → blood carries → target responds.','The hormone is a chemical messenger.'],'Model pancreas releasing insulin into blood; responsive tissues change glucose uptake/storage processes. Keep this preview qualitative. Endocrine secretion is into blood, not an exocrine duct.',visual=v1),slide('I do',3,'Recognition makes the signal specific',['Blood can bring a signal near many cells.','A target cell can recognise it and respond.'],'Think aloud: “Both cells are exposed, so travel alone cannot explain the difference. CellA has the appropriate receptor. The simplified shape represents molecular recognition, not a key operated by a tiny person.”',visual=v2),slide('I do',3,'Homeostasis keeps conditions suitable',['Conditions change; regulation limits departures.','A corrective response reduces the original change.','Some control uses nerves, some uses hormones.'],'Model a raised internal variable and a response tending to lower it. Do not use universal numeric normal ranges. Link suitable temperature to enzyme activity and water balance to cell volume at a conceptual level.',visual=v3),slide('We do',3,'Message-routing desk',['W1. Locate the gland names using the position clues.','Then trace a pancreas hormone from release to response.'],'Use table. All six locations are curriculum gland knowledge; reproductive organs are named matter-of-factly without requiring personal information. Route pancreas→blood→appropriate target tissue.',table=table(['Endocrine structure','Approximate position'],glands,'Schematic location guide; different reproductive organs are listed, not drawn as one anatomy.')),slide('We do',2,'Predict the responding cell',['W2. The same hormone reaches cellsA andB.','Which cell is more likely to respond in this model?'],'Ahas matching receptor. Ask for the missing link if pupil says hormone never reachesB; it does reachB but no matching response is represented.',visual=v2),slide('We do',2,'Control-room repair',['W3. “The variable rose, so the controller always pushes it further up.”','Explain what a negative-feedback response should do.'],'It counteracts the original rise, tending towards suitable limits. Do not claim every biological loop is negative feedback or control is instantaneous.',reveal='A negative-feedback response opposes the departure, rather than automatically amplifying it.'),slide('Hinge',3,'Which explanation links route and recognition?',['Choose the mechanism, not a human-like story.'],'First option correct. Re-teach blooddistribution versus recognition if wrong.',options=[option('The hormone circulates; appropriate target cells recognise it and respond.',True,'Yes. Transport and recognition are different parts of the mechanism.'),option('The hormone chooses only the cells it likes.',False,'Hormones do not choose; molecular recognition and cell machinery determine responses.'),option('Homeostasis means no internal value ever changes.',False,'Regulation responds to changes and helps keep conditions within suitable limits.')]),slide('You do',1,'Build a control explanation',['Choose your response page.','Use a route diagram and a cause-and-effect sentence.'],'All routes target message transport, specificity and regulated conditions. No numerical clinical data are required.'),slide('You do',10,'Make the mechanism visible',['Source → transport → target → response.','Explain why suitable conditions matter.'],'SupportedS1–S4;standardM1–M4;stretchT1–T4. Use a word-bank prompt if needed and record support. Do not require advanced hormone feedback cascades.'),slide('Review',2,'Audience asks about the missing link',['L1. Share a short explanation.','Audience: “How did the message reach that cell, and why did it respond?”'],'A quiet teacher/TA review counts. Pupil improves a route label or distinguishes exposure from response.'),slide('Review',1,'A useful model also has a limit',['The model shows a mechanism.','It does not predict exact timings, hormone amounts or clinical outcomes.'],'Model a precise limit. Keep homeostasis as dynamic regulation; avoid perfect thermostat equivalence.'),slide('Exit',1,'Three linked ideas',['E1. How are endocrine hormones transported?','E2. Why may a non-target cell not respond?','E3. What does homeostasis regulate?'],'E1inblood. E2appropriate recognition/receptor absent in the model. E3internal conditions within suitable limits. Use these to prepare the glucose model.'),slide('Exit',0,'Choose the next useful step',['Gland location • signal route • target recognition • control.'],'Shared exit minute. Accept a labelled arrow chain instead of extended writing.')]
j['pupilPages']=[page('Shared evidence | Signals and conditions','Original conceptual cases; no personal health or medical decision is involved.',[tb(['Endocrine structure','Approximate position'],glands),dict(type='cards',cards=[dict(title='Cell model',text='A hormone is present near both cellsA andB. A has a matching receptor; B lacks that receptor.'),dict(title='Control case',text='An internal variable rises above its usual suitable range. In this model, the control response can reduce that departure.'),dict(title='Conditions case',text='A cell’s enzyme-controlled reactions depend on suitable temperature. Water balance also affects animal-cell volume.')]),response('W1. Trace a message. W2. Predict a responding cell. W3. Explain a corrective response.',3)]),page('Supported route | Label the mechanism','Word bank: endocrine gland; blood; target; receptor; response; suitable range.',[response('S1. Put gland, blood and target cell in order. Say what happens at each step.',4),response('S2. ChooseA orB from the cell model and explain the recognition difference.',3),response('S3. An internal variable rises. Describe the direction of a response that counteracts this rise.',3),response('S4. Give one reason suitable internal conditions matter. Locate the pancreas and thyroid.',4)]),page('Standard route | Explain the control room','Use the shared evidence and accurate biological terms.',[response('M1. Explain how a hormone reaches a target organ, distinguishing release, transport and response.',4),response('M2. Explain why cellA can respond when cellB does not, although both are exposed.',3),response('M3. Explain homeostasis and negative feedback without claiming perfect constancy or that all responses use hormones.',4),response('M4. Name the positions of three endocrine glands and explain one reason internal temperature or water balance matters.',4)]),page('Stretch route | Test the model','Optional deeper reasoning; detailed Higher-tier hormone cascades are not required.',[response('T1. A cell has a matching receptor but its response machinery is damaged. Is receptor presence alone enough to guarantee a normal response? Explain.',4),response('T2. A model response arrives late and the variable briefly passes its target. Does this prove there is no control? Explain one model limitation.',4),response('T3. Compare a broadly circulating chemical message with a directed nerve signal at a conceptual level. Avoid claiming all hormone responses are always slow.',3),response('T4. Explain why a general feedback diagram cannot predict a person’s exact hormone level or diagnose illness.',3)]),page('Exit and reflection | Route, recognition, regulation','Use short explanations or labelled arrows.',[response('E1. How do endocrine hormones travel to tissues?',2),response('E2. Why may a cell fail to respond to a particular hormone?',3),response('E3. What does homeostasis regulate, and why?',3),response('L1. What did your audience ask? Record one improved or defended mechanism.',3),choices('Next useful step',['Locate an endocrine gland.','Trace transport in blood.','Explain receptor specificity.','Describe regulation within limits.'])])]
j['answers']=[qa('Retrieval and We do','R1blood;R2suitable conditions support cell reactions/enzymes and cell integrity;R3no. W1use the six locations in the table, then pancreas→blood→responsive tissue. W2Ahas matching recognition. W3the response should reduce the original rise in the model.'),qa('Hinge','Correct:circulation plus target recognition. Hormones do not consciously choose. Homeostasis permits change while regulating within suitable limits.'),qa('S1 / M1','An endocrine gland releases a hormone into blood. Circulating blood transports it to tissues. Cells with suitable recognition/response machinery respond by changing activity.'),qa('S2 / M2','Ahas the matching receptor;Bdoes not in this model. Both can encounter the hormone. Presence in blood is not the same as an appropriate target response.'),qa('S3 / M3','A corrective response opposes the rise and tends towards suitable limits. Homeostasis regulates an internal environment; it does not mean every value is fixed or that all coordination is hormonal.'),qa('S4 / M4','Pancreas upper abdomen;thyroid neck. Other valid locations:pituitary base ofbrain;adrenals above kidneys;ovaries pelvis;testes scrotum. Suitable temperature supports enzyme-controlled reactions;water balance prevents excessive cell swelling/shrinking.'),qa('T1','No. Recognition is one requirement; downstream cell machinery must also function. The simple receptor picture omits those steps.'),qa('T2','No. Delays and overshoot can occur in regulated systems. A simplified diagram does not show response speeds, competing signals or exact ranges.'),qa('T3','Hormones circulate chemically in blood and affect responsive targets. Nerve impulses travel along neurones to connected targets. Typical timing/range differ, but avoid absolute claims that every hormone is slow or every response identical.'),qa('T4','The model has no individual measurements, calibrated parameters or clinical context. It illustrates a causal organisation, not a diagnostic instrument.'),qa('Exit and assessment','E1bloodstream. E2lack of appropriate receptor/response machinery;use the receptor distinction for core. E3internal conditions within suitable limits so cells function. Secure core:correct route+specificity+dynamic regulation. Re-teach by separately asking “does the signal arrive?” and “can the cell respond?”')]
j['teacherNotes'] += ['Suggested timing:2+3+10+7+3+11+3+1=40minutes.','Interactive Wedo uses the same gland-route, target-recognition and feedback cases. Pupils predict, reveal a mechanism and explain; paperW1–W3 follows the same decisions.','Naming ovaries and testes is part of locating endocrine structures; no pupil anatomy, identity, family history or health disclosure is required.']
j['interactive']=interactive('Message route: predict, test, explain','A qualitative cell-signalling model, not a medical simulation.',[step('What carries an endocrine hormone to tissues?','Blood.','A private duct to every target.',v1,'Endocrine glands release hormones into circulating blood.','A private duct is not the endocrine transport route.'),step('Which model cell can recognise this signal?','A, with the matching receptor.','B, simply because it is nearby.',v2,'Recognition helps determine the target response.','Nearby exposure does not supply the missing receptor.'),step('What does negative feedback do to the original departure?','Counteracts it.','Always amplifies it.',v3,'The response tends to reduce the departure from suitable limits.','Amplifying a change is not negative feedback.')])
save(j)
